<?php require_once 'auth.php';require_admin();header('Content-Type: application/json');$pdo=db();$productId=(int)($_POST['product_id']??0);$materialId=(int)($_POST['material_id']??0);if(!$pdo||!$productId||!$materialId){http_response_code(422);exit;}try{$pdo->prepare('INSERT IGNORE INTO product_variant_materials(product_id,material_id) VALUES(?,?)')->execute([$productId,$materialId]);echo '{"ok":true}';}catch(Throwable $e){http_response_code(422);}
